   tf('سيقرّر مجلس المعهد فتح القاعة المسائية في الشهر القادم.', 'وسينظر مجلس المعهد في الشهر القادم في القاعة المسائية والامتحان الخارجيّ، وسنعود إلى الموضوع بعد قراره.', 'ng', 'سينظر، ولم يُذكر ما سيقرّر.'),
   tap('المس كلمة الفرز التي تفتح الجملة الرئيسة', ['وباختصار:', 'المعهد', 'يملك', 'دليلًا', 'ولا', 'يملك', 'ما', 'يكفي'], 'وباختصار:'),
   tap('المس علامة التفصيل الداعم', ['فقد', 'أجرت', 'لجنة', 'الطلّاب', 'استطلاعًا', 'على', 'الخرّيجين'], 'فقد'),
   tap('المس علامة الاستطراد', ['كما', 'كان', 'يفعل،', 'على', 'قوله،', 'الشيخ', 'الذي', 'علّمه'], 'قوله،'),
   dic('لكلّ فقرة جملة رئيسة وما عداها تفاصيل.', ['لكل فقرة جملة رئيسة وما عداها تفاصيل']),
