   seq('رتّب طبقات الهرم من القمّة', [('up', 'فكرة النصّ كلّه'), ('book', 'أفكار الفقرات'), ('percent', 'التفاصيل الداعمة'), ('window', 'الاستطراد في الحاشية')]),
