   card('يُحسم', 'يُقرَّر فيه قرارًا نهائيًّا', 'لم يُحسم أمر القاعة بعد، وحُسم الخلاف على الجملة الثالثة بقاعدة، ويُحسم البند الرابع الخميس، ولا يُحسم شيء بالصوت، ويحسم أبو محمد الخلاف بالجدول، ويحسمه الجدّ حسن بمثل.'),
   card('يخشى', 'يخاف من', 'تخشى سلمى أن يتحوّل البند إلى طلبات، وفلنحسمه بقاعدة لا بما نخشى، قالت هند؛ ويخشى كين الامتحان الخارجيّ، ولا يخشى فهد سؤالًا على الهواء، ولا يخشى الجدّ حسن أحدًا.'),
