   mcq('ماذا تدوّن ليلى في الاجتماع؟', ['كلّ ما يُقال', 'القرارات لا الكلام: الجملة كما استقرّت، وسبب الحذف، والقاعدة، والملحق، والقارئ، والوقت', 'الأسماء فقط'], 1, 'خمسة أسطر، ثمّ قرار سادس: نسخة إلى ريم، وهي الطريقة التي يدوّن بها يوسف اجتماعات أبي محمد.'),
   match('الجملة ووظيفتها', [('الأولى', 'ما يقوله التقرير: يثبت باستطلاع أنّ أغلبهم يقرؤون'), ('الثانية', 'ما يسنده: استطلاع برقم واحد وحلقة تضاعفت'), ('الثالثة', 'ما يبقى مفتوحًا: القاعة والامتحان لم يُحسما'), ('الملحق', 'العيّنة وبقية الأرقام ونسخة التقرير')]),
   match('الصيغة ووظيفتها', [('مسودّتي للجملة الأولى كذا', 'اقتراح'), ('أقترح تعديلين، لأنّ…', 'تعديل بتعليل'), ('أتّفق في المبدأ وأختلف في رقم واحد', 'قبول جزئيّ'), ('فلنحسمه بقاعدة لا بما نخشى', 'الحسم بقاعدة')]),
   match('ما يُذكر وما يُرفق', [('القاعة المسائية', 'تُذكر: البند الرابع'), ('الامتحان الخارجيّ', 'يُذكر: البند الرابع'), ('نسبة المعلّمين إلى الطلّاب', 'تُرفق: ليست على الجدول'), ('عيّنة الاستطلاع', 'تُرفق: المجلس لا يحتاج إليها في الملخّص')]),
   order('رتّب القاعدة', ['ما', 'سيقرّر', 'فيه', 'المجلس', 'يُذكر،', 'وما', 'لا', 'يقرّر', 'فيه', 'يُرفق.']),
   order('رتّب القبول الجزئيّ', ['أتّفق', 'في', 'المبدأ', 'وأختلف', 'في', 'رقم', 'واحد.']),
   order('رتّب جواب المنفيّ', ['أليس', 'كذلك؟', 'بلى،', 'البند', 'الرابع.']),
   pic('من الاجتماع: «ليلى جلست إلى طرف الطاولة بدفتر الملاحظات»', ['pen', 'cup', 'phone'], 0),
   pic('من الاجتماع: «للبند ثلاث دقائق لا أكثر»', ['clock', 'calendar', 'bell'], 0),
