   cloze('أكمل التعديل', '«إيجابيًّا» ___ نحن لا ما يقوله التقرير، و«يؤكّد» فعل نقل ___، والأدقّ «يثبت ___».', ['رأينا', 'واثق', 'باستطلاع'], ['دليلنا', 'محايد', 'بالقصّة']),
   cloze('أكمل الحسم', 'فلنحسمه ___ لا بما نخشى: ما سيقرّر فيه المجلس ___، وما لا يقرّر فيه ___.', ['بقاعدة', 'يُذكر', 'يُرفق'], ['بصوت', 'يُحذف', 'يُنسى']),
   cloze('أكمل الملخّص والملحق', 'رقم ___ في الملخّص، والعيّنة والباقي في ___ من ورقة، والوقت ثمان وثلاثون ___.', ['واحد', 'ملحق', 'ثانية'], ['كبير', 'جدول', 'دقيقة']),
